export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "19:45。M 區。緊急觀察走廊被臨時清空了一側。摺疊桌。筆電。文件箱。像一個倉促搭起來的指揮室。觀察窗的綠光還在背後。呼吸曲線還在跑。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪坐在摺疊椅上。三十分鐘的短睡沒有讓她清醒多少。食物還堵在胃裡。不是飽。是身體還不確定自己可以吃東西了。她看著觀察窗。窗後那個人的胸口還在起伏。很慢。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯M-00。基準母體。維持中。朝倉紗英。死了十年。⋯⋯還在呼吸。⋯⋯三十分鐘。只睡了三十分鐘。不夠。但不睡的話身體會垮。日下部說的。他說——先吃。先睡。資料我們看著。⋯⋯他看著了。他看見了。左眉的疤。死亡登記。十年。⋯⋯現在呢。現在誰要來。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "走廊盡頭的門開了。腳步聲。不是一個人。三個人。第一個走在前面。深色風衣。銀框眼鏡。黑色短髮。步伐穩。不快不慢。像走進過很多次這種走廊。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第二個人穿深色西裝。手裡拿著一個硬殼公事包。第三個人穿淺色醫療外套。胸前掛著一面識別證。國家級。三個人都沒有帶武裝人員。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "走在前面的人停在摺疊桌前。她看了觀察窗一眼。看了工作站螢幕一眼。看了日下部一眼。然後她看了澪。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯她知道我在這裡。她看了我。不是驚訝。不是同情。是確認。像在確認一個變數已經到了現場。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部站起來。他沒有伸手。沒有打招呼。他看著那個人。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "凪原唯。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "日下部刑警。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的聲音平。像在讀標題。不帶情緒。不帶敵意。也不帶客氣。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯凪原唯。前研究中心科學負責人。現——什麼。內閣。危機科學。⋯⋯她就是那個名字。Chapter 14 審查委員名單裡的名字。Chapter 15 修訂監修欄裡的 Y. NAGIHARA。Chapter 16 跨部門協調責任人。⋯⋯她一直在那裡。一直在文件邊緣。現在走到中間了。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原沒有坐下。她站在摺疊桌前。身後的法律顧問打開公事包。開始排列文件夾。每一份都貼著編號標籤。醫療協調人走到觀察窗旁邊。他看了監測器。看了呼吸曲線。沒有碰任何設備。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "在替代維持和外部醫療評估完成前，不能突然中止 M-00。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第一句話。不是問候。不是解釋。是要求。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯不能中止。她第一句話就是不能中止。不是——妳母親在裡面。不是——我知道妳發現了。是——不能中止 M-00。像 M-00 是一個設備。像裡面那個人是參數。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.AsakuraMio_Angry },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "悠真房間已經依法控制。外部醫療已經接管。紗英身分與死亡紀錄的矛盾已經是當輪證據。國安通知不能抹除搜索結果。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他的語氣也平。像在讀勤務日誌。每一句都是已經完成的事實。不是談判。是底線。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "我知道。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "兩個字。沒有辯護。沒有試圖撤銷。她只是承認了地方警方已經做到的範圍。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "那妳來做什麼。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "M-00 的安全資料只有研究方掌握。外部醫師需要它才能判斷——能不能搬。能不能停。怎麼停。我不提供，你們只能猜。猜錯了，裡面那個人會死。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她沒有看澪。她看著日下部。像在跟負責程序的人說話。不是在跟家屬說話。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯她在繞過我。她在跟日下部談。把我排除在外。像我是情緒。不是當事人。⋯⋯可是她說的——不能猜。猜錯了會死。⋯⋯那是真的嗎。那是真的嗎。媽媽真的不能直接拔線嗎。⋯⋯我不知道。我不懂醫療。我只知道她還在呼吸。我只知道她死了十年還在呼吸。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.AsakuraMio_Angry },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "外部醫師從觀察窗旁邊走過來。他聽完了前面全部的對話。他沒有看凪原的文件。他看著她的臉。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "我只聽醫療資料。妳說的系統風險，另算。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原看了他一眼。點了一下頭。像是預期中的回答。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "可以。醫療資料先。系統資料之後。分開。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她身後的法律顧問把第一份文件推到桌面上。編號 01。封面寫著——M-00 現行維持方式。最低必要醫療摘要。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.CabinetLegalAdvisor, character: "內閣法律顧問", dialogue: "每份資料有書面目錄、披露時間與責任人。披露不構成免責。已取得的證據不撤回。地方警方保留擴大搜索及追責權限。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "法律顧問的聲音像在讀條文。沒有情緒。沒有傾向。不替凪原辯護。也不阻止任何人記錄。他只維護程序框架。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "妳提供安全資料，不代表調查停止。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "我知道。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "又是兩個字。同樣的語氣。同樣的沒有辯護。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯她不害怕。她不害怕調查。她不害怕搜索。她害怕的是——M-00 被粗暴中止。不是因為裡面是她媽媽。是因為 M-00 是——基準。參照。母體。⋯⋯她在保護的不是人。是系統。⋯⋯可是她說的醫療風險——如果是真的——那我也不能讓人直接拔線。⋯⋯我恨這個。我恨她用安全當理由。我恨安全可能是真的。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原把文件夾打開。裡面是列印出來的醫療參數表。呼吸設定。循環支持。自律神經調節。抗癲癇用藥。神經刺激參數。屏蔽環境規格。全部有日期。全部有設備型號。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "這是 M-00 的現行維持方式。不是全部病歷。是外部醫師判斷搬移與停藥風險所需的最低資料。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "醫療協調人走到桌邊。他拿起文件。翻了一頁。翻了一頁。再翻了一頁。然後他看向外部醫師。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.NationalMedicalCoordinator, character: "國家級醫療協調人", dialogue: "參數格式與現行設備一致。可以移交外部醫療團隊核驗。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "外部醫師接過文件。他開始看。一頁一頁。呼吸。循環。自律。用藥。刺激。屏蔽。他看得慢。像在讀術前評估單。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原站在原地。她沒有催促。沒有解釋。她等著。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部走到澪旁邊。他壓低聲音。只有她聽得到。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "她帶了法律顧問和醫療協調人。沒有帶武裝。沒有要求我們退出。⋯⋯她不是來搶的。她是來換的。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯來換的。用最低資料換——不粗暴中止。不擴大搜索。不讓外部醫師在沒有資料的情況下冒險。⋯⋯她在保護 M-00。也在保護自己。⋯⋯可是她沒有要求我們放棄調查。法律顧問說了——披露不構成免責。證據不撤回。⋯⋯她知道她已經控制不住了。她只是在控制失控的速度。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "20:05。外部醫師看完了最後一頁。他把文件放下。看著凪原。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "這些參數如果是真的——直接拔線或搬離確實有風險。但我需要獨立核驗。不是看妳給的文件。是看設備。看藥物。看即時數值。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "可以。醫療協調人在場。外部團隊主導核驗。研究方只提供接入權限。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她沒有猶豫。像是早就準備好這個答案。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯她準備好了。她來之前就準備好了。每一步。每一份文件。每一個讓步。都是算過的。⋯⋯她不是良心發現。她是——被逼到了牆角。然後在牆角裡畫了一條線。線裡面是她還能保住的東西。線外面是她已經保不住的。⋯⋯可是那條線畫在——我媽媽身上。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "20:15。臨時指揮室。法律顧問把第二份文件推到桌面上。編號 02。封面寫著——M-00 既有故障與中斷紀錄。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.CabinetLegalAdvisor, character: "內閣法律顧問", dialogue: "第二份。系統層面。與醫療資料分開記錄。閱覽者依分層權限。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部看了一眼封面。他沒有立刻打開。他看向凪原。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "系統資料跟醫療資料分開。可以。但我要先說一條。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "所有資料分成三類。醫療事實——外部醫師獨立確認。系統觀察——故障紀錄、血統圖、模型支持。政策主張——妳和國家安全評估。三類分開記錄。不混。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原看了他一眼。眼鏡後面的眼神沒有波動。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "可以。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "三個字。第三次「可以」。每一次都是讓步。每一次都精確到剛好。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯她什麼都答應。什麼都「可以」。像她早就知道日下部會要求什麼。像她把每一個要求都算進了讓步的範圍。⋯⋯這不是投降。這是控制。控制讓步的幅度。控制讓步的順序。讓你覺得她配合了。讓你覺得她妥協了。⋯⋯可是她從頭到尾沒有說過一句——對不起。沒有說過一句——她是我母親。沒有說過一句——我們錯了。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.AsakuraMio_Angry },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "20:20。醫療協調人把一份程序清單遞給外部醫師。清單上列著核驗步驟。設備接入。藥物核對。即時數值讀取。替代維持評估。分階段撤離條件。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.NationalMedicalCoordinator, character: "國家級醫療協調人", dialogue: "核驗程序建議在 M-00 外部醫療工作站進行。不進入房間。不更動現行設定。只讀取。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "可以。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部點了一下頭。三浦在角落記錄。法律顧問把第三份文件放到桌上。編號 03。封面寫著——與紗英直接相關之函館第一層事故資料。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪看見了那個封面。函館。第一層。事故。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯函館。⋯⋯媽媽。⋯⋯函館跟媽媽有關。⋯⋯十年前。北海道。出差。急病。病逝。⋯⋯那是假的。全部都是假的。⋯⋯函館發生了什麼。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "凪原沒有打開第三份文件。她只是把它放在桌上。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.NagiharaYui, character: "凪原唯", dialogue: "函館資料在醫療核驗之後。順序不能跳。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.NagiharaYui_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她在控制順序。先醫療。再系統。最後事故。每一層都有門檻。每一層都要等上一層完成。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯她在控制節奏。她在控制我什麼時候知道什麼。⋯⋯我恨她。⋯⋯可是我恨她的同時——她在說的是——不能拔掉我媽媽。⋯⋯我恨的是——她說「不能拔掉」的時候。她說的不是媽媽。是 M-00。", background: Background.Chapter_20_Ch20_Act1_S0, portrait: Portrait.AsakuraMio_Angry },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "20:25。臨時指揮室。文件排列在桌上。01。02。03。綠光從觀察窗透過來。呼吸曲線在跑。凪原站在桌前。法律顧問在她身後。醫療協調人在窗邊。日下部在桌對面。三浦在角落。外部醫師手裡拿著第一份文件。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "沒有人離開。沒有人坐下。像一場還沒開始的談判。又像一場已經開始了的投降。", background: Background.Chapter_20_Ch20_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "距下一次星期一 06:13——約五日九小時四十八分鐘。", background: Background.Chapter_20_Ch20_Act1_S0 },
];
